```python
def stable_matching(proposers: dict, receivers: dict) -> dict:
    # Precompute rank mapping for each receiver to check preferences in O(1) time
    receiver_rank = {
        r: {p: rank for rank, p in enumerate(prefs)}
        for r, prefs in receivers.items()
    }

    # Track the index of the next receiver each proposer will propose to
    next_proposal_idx = {p: 0 for p in proposers}

    # Track current match for receivers: receiver -> proposer
    receiver_match = {}

    # Track free proposers; sort to process in plain string order
    free_proposers = sorted(proposers.keys())

    while free_proposers:
        # Process free proposers in plain string order
        p = free_proposers.pop(0)

        # Get the next receiver to propose to
        target_receiver = proposers[p][next_proposal_idx[p]]
        next_proposal_idx[p] += 1

        if target_receiver not in receiver_match:
            # Receiver is free, accepts proposal
            receiver_match[target_receiver] = p
        else:
            current_partner = receiver_match[target_receiver]
            ranks = receiver_rank[target_receiver]

            # Check if receiver prefers the new proposer
            if ranks[p] < ranks[current_partner]:
                receiver_match[target_receiver] = p
                # Previous partner becomes free; insert while maintaining sorted order
                free_proposers.append(current_partner)
                free_proposers.sort()
            else:
                # Proposer rejected; remains free
                free_proposers.append(p)
                free_proposers.sort()

    # Return mapping from proposer -> receiver
    return {p: r for r, p in receiver_match.items()}
